DROP TABLE IF EXISTS `system`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `system` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title_id` int NOT NULL,
  `total_athletes` int NOT NULL,
  `total_group` int NOT NULL,
  `max_player` int DEFAULT NULL,
  `stage` varchar(255) NOT NULL,
  `type_table` varchar(100) NOT NULL,
  `page_vid` varchar(255) NOT NULL,
  `label_string` varchar(255) NOT NULL,
  `kol_game_string` varchar(255) NOT NULL,
  `choice_flag` tinyint(1) NOT NULL,
  `score_flag` int NOT NULL,
  `visible_game` tinyint(1) NOT NULL,
  `stage_exit` varchar(100) NOT NULL,
  `mesta_exit` int NOT NULL,
  `no_game` varchar(15) NOT NULL,
  `sex` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `system_title_id` (`title_id`),
  CONSTRAINT `system_ibfk_1` FOREIGN KEY (`title_id`) REFERENCES `titles` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1125 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
