DROP TABLE IF EXISTS `teams`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `teams` (
  `id` int NOT NULL AUTO_INCREMENT,
  `team_name` varchar(70) NOT NULL,
  `region` varchar(255) DEFAULT NULL,
  `coach_team` varchar(255) DEFAULT NULL,
  `r_sum` int NOT NULL,
  `title_id` int DEFAULT NULL,
  `id_pl1` int DEFAULT NULL,
  `r_pl1` int NOT NULL,
  `id_pl2` int DEFAULT NULL,
  `r_pl2` int NOT NULL,
  `id_pl3` int DEFAULT NULL,
  `r_pl3` int NOT NULL,
  `id_pl4` int DEFAULT NULL,
  `r_pl4` int NOT NULL,
  `id_pl5` int DEFAULT NULL,
  `r_pl5` int NOT NULL,
  `team_full` varchar(100) DEFAULT NULL,
  `team_sex` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `team_title_id` (`title_id`),
  KEY `team_id_pl1` (`id_pl1`),
  KEY `team_id_pl2` (`id_pl2`),
  KEY `team_id_pl3` (`id_pl3`),
  KEY `team_id_pl4` (`id_pl4`),
  KEY `team_id_pl5` (`id_pl5`),
  CONSTRAINT `teams_ibfk_1` FOREIGN KEY (`title_id`) REFERENCES `titles` (`id`),
  CONSTRAINT `teams_ibfk_2` FOREIGN KEY (`id_pl1`) REFERENCES `players` (`id`),
  CONSTRAINT `teams_ibfk_3` FOREIGN KEY (`id_pl2`) REFERENCES `players` (`id`),
  CONSTRAINT `teams_ibfk_4` FOREIGN KEY (`id_pl3`) REFERENCES `players` (`id`),
  CONSTRAINT `teams_ibfk_5` FOREIGN KEY (`id_pl4`) REFERENCES `players` (`id`),
  CONSTRAINT `teams_ibfk_6` FOREIGN KEY (`id_pl5`) REFERENCES `players` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

